#!/usr/bin/env node
// Regenerates data/catalog.json and src/catalog-data.ts.
//   node scripts/generate.mjs            offline: overrides only (no network)
//   node scripts/generate.mjs --live     also fetch provider list-models endpoints
//                                        (keys from env; providers without a key are skipped)
//                                        and OpenRouter's public /api/v1/models
//   --diff-out <file>   write the readable PR diff (markdown) there
//   --check             exit 1 if the generated files differ from what is committed
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { buildCatalog, diffCatalogs, formatDiffMarkdown, stripModelsPrefix } from './lib.mjs';

const root = fileURLToPath(new URL('..', import.meta.url));
const args = process.argv.slice(2);
const flag = (n) => args.includes(n);
const val = (n) => (args.includes(n) ? args[args.indexOf(n) + 1] : undefined);

/** provider -> list-models request. `key` is the env var; skipped when unset. */
export const LIST_ENDPOINTS = {
  anthropic: {
    url: 'https://api.anthropic.com/v1/models?limit=1000',
    key: 'ANTHROPIC_API_KEY',
    headers: (k) => ({ 'x-api-key': k, 'anthropic-version': '2023-06-01' }),
  },
  openai: { url: 'https://api.openai.com/v1/models', key: 'OPENAI_API_KEY', headers: bearer },
  gemini: {
    url: 'https://generativelanguage.googleapis.com/v1beta/models?pageSize=1000',
    key: 'GEMINI_API_KEY',
    headers: (k) => ({ 'x-goog-api-key': k }),
    pick: (j) =>
      j.models
        .filter((m) => (m.supportedGenerationMethods ?? []).includes('generateContent'))
        .map((m) => ({ id: m.name, name: m.displayName })),
  },
  xai: { url: 'https://api.x.ai/v1/models', key: 'XAI_API_KEY', headers: bearer },
  mistral: { url: 'https://api.mistral.ai/v1/models', key: 'MISTRAL_API_KEY', headers: bearer },
  deepseek: { url: 'https://api.deepseek.com/models', key: 'DEEPSEEK_API_KEY', headers: bearer },
  moonshot: { url: 'https://api.moonshot.ai/v1/models', key: 'MOONSHOT_API_KEY', headers: bearer },
  groq: { url: 'https://api.groq.com/openai/v1/models', key: 'GROQ_API_KEY', headers: bearer },
  together: {
    url: 'https://api.together.xyz/v1/models',
    key: 'TOGETHER_API_KEY',
    headers: bearer,
    pick: (j) =>
      (Array.isArray(j) ? j : j.data)
        .filter((m) => !m.type || m.type === 'chat')
        .map((m) => ({ id: m.id, name: m.display_name })),
  },
  openrouter: { url: 'https://openrouter.ai/api/v1/models', key: null, headers: () => ({}) }, // public
};
function bearer(k) {
  return { authorization: `Bearer ${k}` };
}

async function getJson(url, headers) {
  const res = await fetch(url, { headers, signal: AbortSignal.timeout(30000) });
  if (!res.ok) throw new Error(`${res.status} ${res.statusText}`);
  return res.json();
}

async function fetchLive() {
  const live = {},
    skipped = [];
  for (const [pid, ep] of Object.entries(LIST_ENDPOINTS)) {
    if (pid === 'openrouter') continue;
    const key = process.env[ep.key];
    if (!key) {
      skipped.push(`${pid} (no ${ep.key})`);
      continue;
    }
    try {
      const j = await getJson(ep.url, ep.headers(key));
      const rows = ep.pick
        ? ep.pick(j)
        : (j.data ?? []).map((m) => ({ id: m.id, name: m.display_name ?? m.name }));
      live[pid] = rows.map((r) => ({ id: stripModelsPrefix(r.id), name: r.name }));
      console.error(`live ${pid}: ${live[pid].length} models`);
    } catch (e) {
      // A failing provider must not silently drop its models from the diff; fail loudly.
      throw new Error(`list-models for ${pid} failed: ${e.message}`);
    }
  }
  let openrouter = [];
  try {
    openrouter = (await getJson(LIST_ENDPOINTS.openrouter.url, {})).data ?? [];
    console.error(`openrouter: ${openrouter.length} models`);
  } catch (e) {
    throw new Error(`OpenRouter fetch failed: ${e.message}`);
  }
  if (skipped.length) console.error(`skipped (no secret): ${skipped.join(', ')}`);
  return { live, openrouter, skipped };
}

export function toTs(catalog) {
  return (
    `// GENERATED by scripts/generate.mjs from data/overrides.json. Do not edit.\n` +
    `import type { ModelCatalog } from './types.js';\n\n` +
    `export const CATALOG: ModelCatalog = ${JSON.stringify(catalog, null, 2)} as unknown as ModelCatalog;\n`
  );
}

async function main() {
  const overrides = JSON.parse(readFileSync(`${root}data/overrides.json`, 'utf8'));
  let previous;
  try {
    previous = JSON.parse(readFileSync(`${root}data/catalog.json`, 'utf8'));
  } catch {
    /* first run */
  }
  const extra = flag('--live') ? await fetchLive() : { live: {}, openrouter: [] };
  // Offline runs must be deterministic: reuse the previous run's date unless regenerating live.
  const prevDate = Date.parse(previous?.generatedOn);
  const now = flag('--live') || Number.isNaN(prevDate) ? Date.now() : prevDate;
  const { catalog, report } = buildCatalog({
    overrides,
    live: extra.live,
    openrouter: extra.openrouter,
    now,
  });
  const json = JSON.stringify(catalog, null, 2) + '\n';
  const ts = toTs(catalog);
  if (flag('--check')) {
    const same = (f, s) => {
      try {
        return readFileSync(`${root}${f}`, 'utf8') === s;
      } catch {
        return false;
      }
    };
    if (!same('data/catalog.json', json) || !same('src/catalog-data.ts', ts)) {
      console.error(
        'catalog.json / catalog-data.ts are out of date: run `npm run generate -w @johnhenry/aimatey-models`'
      );
      process.exit(1);
    }
    return;
  }
  writeFileSync(`${root}data/catalog.json`, json);
  writeFileSync(`${root}src/catalog-data.ts`, ts);
  const md = formatDiffMarkdown(
    diffCatalogs(previous, catalog),
    flag('--live') ? report : undefined,
    { today: catalog.generatedOn }
  );
  const out = val('--diff-out');
  if (out) writeFileSync(out, md);
  console.log(md);
}

if (import.meta.url === `file://${process.argv[1]}`)
  main().catch((e) => {
    console.error(e.message);
    process.exit(1);
  });
